export default function typeformClickupRequest({ response, listIds }) {
  if (!response || typeof response !== 'object' || Array.isArray(response) || !Array.isArray(response.answers) || !response.definition || !Array.isArray(response.definition.fields)) {
    throw new Error('Expected a complete Typeform response with answers and field definitions');
  }
  const titles = new Map(), answers = new Map();
  for (const field of response.definition.fields) {
    if (!field || typeof field.id !== 'string' || typeof field.title !== 'string' || titles.has(field.id)) throw new Error('Invalid or duplicate Typeform field definition');
    titles.set(field.id, field.title);
  }
  for (const answer of response.answers) {
    if (!answer || typeof answer !== 'object' || !answer.field || typeof answer.field.id !== 'string' || typeof answer.type !== 'string') throw new Error('Invalid Typeform answer');
    const title = titles.get(answer.field.id);
    if (!title) continue;
    if (answers.has(title)) throw new Error('Duplicate answered question title: ' + title);
    const value = answer[answer.type];
    answers.set(title, answer.type === 'choice' && value && typeof value === 'object' ? value.label : value);
  }
  const category = answers.get('What type of a request are you making?');
  const categories = ['Document Request', 'Presentation Request', 'Update Request', 'Workflow Request'];
  if (!categories.includes(category)) return { matched: false, listId: 'UNROUTED', name: 'Unrouted request', description: '', priority: null };
  const listId = listIds?.[category];
  if (typeof listId !== 'string' || !/^\d+$/.test(listId)) throw new Error('Configure the ClickUp list ID for ' + category);
  const requiredText = (title) => {
    const value = answers.get(title);
    if (typeof value !== 'string' || !value.trim()) throw new Error('Missing text answer: ' + title);
    return value;
  };
  const name = requiredText('Give this request a short title.');
  const details = requiredText('Describe in detail what you would like to see happen for this request.');
  const requester = requiredText('Your full name'), email = requiredText('Your email address');
  const urgency = answers.get('How urgent is this request?');
  let priority = null;
  if (urgency !== undefined && urgency !== null && urgency !== '' && urgency !== 0) {
    if (!Number.isInteger(urgency) || urgency < 1 || urgency > 4) throw new Error('Urgency must be a ClickUp priority number from1 to4, or blank/0 for no priority');
    priority = urgency;
  }
  return { matched: true, listId, name, description: details + '\n\nRequested by:\n' + requester + '\n' + email, priority };
}

